class LamportClock {
  constructor(start){ this.t = start || 0; }
  // local event: tick and return the new timestamp
  send(){ this.t = this.t + 1; return this.t; }
  // receive a message stamped msgT; return the receive timestamp
  recv(msgT){ this.t = Math.max(this.t, msgT); return this.t; }
}

