// stored: { value, vclock: {nodeId: counter}, wallMs }
// incoming: same shape, from another replica
function resolveWrite(stored, incoming) {
  if (!stored) return incoming;

  // decide which version is newer
  if (incoming.wallMs > stored.wallMs) {
    return incoming;          // incoming is newer, keep it
  }
  if (incoming.wallMs < stored.wallMs) {
    return stored;            // stored is newer, drop incoming
  }
  // equal wall time: keep the one with the larger value string
  return incoming.value > stored.value ? incoming : stored;
}
